"use strict";(globalThis.webpackChunkstory=globalThis.webpackChunkstory||[]).push([[62064],{63992(e){e.exports=JSON.parse('{"tag":{"label":"responsible-ai","permalink":"/docs/tags/responsible-ai","allTagsPath":"/docs/tags","count":7,"items":[{"id":"ai-900/workshop-8-responsible-ai/rai-principles","title":"1. Microsoft\'s Responsible AI Principles","description":"Microsoft\'s 6 Responsible AI principles \u2014 definition, real-world examples, failure cases, and the unavoidable trade-offs between principles when they conflict.","permalink":"/docs/ai-900/workshop-8-responsible-ai/rai-principles"},{"id":"ai-900/workshop-2-azure-ai/azure-ai-overview","title":"1. What is Azure AI?","description":"Understand what Azure AI is, why organizations use managed AI services instead of building from scratch, and how Azure AI Foundry serves as the unified development platform.","permalink":"/docs/ai-900/workshop-2-azure-ai/azure-ai-overview"},{"id":"ai-900/workshop-4-azure-ml/azure-ml-tools","title":"2. Azure ML Development Tools and Responsible AI","description":"Explore the three development approaches in Azure ML \u2014 AutoML, Designer, and Notebooks \u2014 and understand the responsible AI tools built into the platform.","permalink":"/docs/ai-900/workshop-4-azure-ml/azure-ml-tools"},{"id":"ai-900/workshop-8-responsible-ai/azure-rai-tools","title":"2. Azure Tools for Responsible AI","description":"Azure tools that operationalize Responsible AI \u2014 the Responsible AI Dashboard in Azure ML, Azure AI Content Safety, Transparency Notes, and how to embed RAI practices across the full AI lifecycle.","permalink":"/docs/ai-900/workshop-8-responsible-ai/azure-rai-tools"},{"id":"ai-900/workshop-6-computer-vision/azure-vision-services","title":"2. Azure Vision Services in Depth","description":"Azure Vision services in depth \u2014 Azure AI Vision, Custom Vision, Face API, and Document Intelligence \u2014 with capability tables, industry use cases, and exam-critical service selection scenarios.","permalink":"/docs/ai-900/workshop-6-computer-vision/azure-vision-services"},{"id":"ai-900/workshop-8-responsible-ai/rai-case-studies-exam-prep","title":"3. Case Studies and AI-900 Exam Preparation","description":"Real-world case studies applying RAI principles across industries, plus a comprehensive AI-900 exam preparation guide covering all 8 workshops with key concepts and service selection patterns.","permalink":"/docs/ai-900/workshop-8-responsible-ai/rai-case-studies-exam-prep"},{"id":"ai-900/workshop-7-generative-ai/responsible-genai","title":"3. Responsible AI for Generative Systems","description":"Understand the unique Responsible AI risks of generative systems \u2014 hallucination, bias amplification, copyright, and deepfakes \u2014 and the Azure safety stack that mitigates them.","permalink":"/docs/ai-900/workshop-7-generative-ai/responsible-genai"}],"unlisted":false}}')}}]);